/* ITC-only business walkthrough; HUL and all other profiles keep their existing content. */
(()=>{
 const id='itc',c=window.COMPANIES.find(c=>c.id===id),previous=window.companyPrimer;
 const root='https://itcportal.com/',business=root+'itc-businesses/';
 const urls={profile:root+'about-itc/our-profile.html',fmcg:business+'fmcg.html',food:business+'fmcg/food.html',cigarettes:business+'fmcg/cigarette.html',agri:business+'agri-business.html',paper:business+'paperboards-and-specialty-papers.html',packaging:business+'packaging.html',technology:business+'Information-Technology.html',group:business+'group-companies.html'};
 const source=window.COMPANY_FINANCIALS[id].source;
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const note=(url,label,location='')=>`<p class="source-note"><a href="${url}" target="_blank" rel="noopener">${label} ↗</a>${location?` · ${location}`:''}</p>`;
 c.summary='Aashirvaad, Sunfeast and Classmate are familiar faces of a business that also sells cigarettes, agricultural products, paper and packaging.';
 c.description="ITC sells familiar foods, cigarettes, personal-care goods and stationery. It also buys and supplies crops, makes paper and packs, and has a company that helps other businesses with computer systems. These jobs have different customers and costs, so a biscuit brand alone cannot explain the whole company.";
 c.money="ITC records sales from goods it supplies, including packaged products, crops, paper and packaging, while ITC Infotech in the group earns from technology services. Buying materials, making goods, paying employees, transporting deliveries, advertising and taxes reduce what remains as profit. Each business must be understood on its own terms.";
 window.COMPANY_OVERVIEWS[id]={"customers": "Households buy the consumer goods in shops or online. Other businesses buy crops, paper, packaging and computer-system services. Shops and distributors, which buy stock and resell it, can be ITC’s direct customers even when households use the final products.", "drivers": "What each business sells, how much customers buy, the price charged and the costs of doing the work. A familiar food brand does not tell us which of ITC’s businesses earns the most."};
 c.watch=[
 ['What is happening to the cigarette business?','Are quantities, pricing and tax changes telling the same story, or different ones?'],
 ['Are the other consumer businesses building profitable demand?','Do food, personal-care and stationery sales cover their ingredients, manufacturing, distribution and brand-building costs?'],
 ['Where are paper and packaging in their business cycle?','Are selling prices and demand keeping up with wood, pulp, energy and factory costs?'],
 ['How does buying agricultural products turn into cash?','Do crop availability, commodity prices, export conditions and customer payments support the business?'],
 ['What is ITC doing with the cash its businesses generate?','Is money going into useful investment, acquisitions or distributions, and what evidence shows the results?'],
 ['Are the reporting boundaries and totals comparable?','Have subsidiaries, the hotel separation, internal sales or tax definitions changed what the figures include?']
 ];
 window.COMPANY_RESEARCH_GUIDES[id]=[
 'Read the cigarette business commentary together with its segment result. Where quantities are disclosed, separate them from selling-price changes. Compare revenue on the stated tax basis: a higher tax component can lift a gross sales figure without representing the same increase in demand or earnings. Check the dated tax-comparability note in the financial table at the end.',
 'Use the FMCG – Other products segment and its category commentary. Volume means quantity sold; mix means which products and formats customers choose. Follow sales, segment results and spending together across comparable periods. The segment bundles many brands, so its profit is not the profit of Aashirvaad, Classmate or any one brand.',
 'Read the paper and packaging review alongside segment results, selling prices, input costs and factory utilisation, where disclosed. Utilisation means how much available production capacity is being used. Imported supply and competing capacity can affect prices. Compare the same year or quarter rather than mixing a full-year result with a seasonal quarter.',
 'Read the agri review for crop conditions, sourcing, customer demand and policy or trade disruptions. Then inspect inventory, receivables (money customers still owe) and operating cash flow. Procurement can require cash before the final sale is collected. Higher commodity prices can raise revenue without a matching increase in quantities or profit.',
 'Start with operating cash flow, then read investment spending and acquisition notes. Profit includes accounting entries and is not the same as cash collected. Ask what an investment cost, how it is expected to earn, and what subsequent disclosures show. Do not assume a new brand or factory is successful merely because ITC can fund it.',
 'Check standalone versus consolidated labels before comparing periods. The parent-company table here excludes subsidiaries’ sales as direct business rows. Deduct internal business-to-business sales when reconciling reported business activity to outside sales. Read the hotel and subsidiary notes, and use the same tax treatment and reporting period. The “Other businesses” row is not a shortcut for ITC Infotech’s sales or profit.'
 ];
 c.risks=[
 ['Dependence on a regulated tobacco business','Changes in tobacco taxes, restrictions, consumer demand or illicit competition can affect cigarette sales and earnings. Read this business separately even when the food brands attract most of your attention.'],
 ['More consumer brands do not automatically mean more profit','Ingredients, advertising, distribution, competition and new launches cost money. A growing brand portfolio can take time to earn adequate returns; the reported bundle of businesses can also hide differences between categories.'],
 ['Paper and agricultural prices can move against the business','Selling prices, harvests, wood and energy costs need not move together. A factory or a stock of commodities can absorb cash during a weak period. Read both the earnings and the cash needed to support activity.'],
 ['Investment does not deliver what was expected','Factories, acquisitions and new categories can require spending before they earn money. Ask whether later results support the original case for investing, rather than judging only the announcement.'],
 ['The headline figure hides a change in scope','Tax changes, acquisitions, internal transfers and the hotel separation can affect comparisons. First establish what the number measures, then ask whether the underlying business improved.']
 ];
 c.update=['A familiar ITC name can describe a different reporting business','ITC Infotech is a subsidiary, while ITC Hotels is now a separate listed company that ITC identifies as an associate. These relationships matter when reading the accounts. The parent-company figures at the end are not a combined sales statement for everything with ITC in its name.'];
 c.question='If ITC’s agri business supplies ingredients to its foods business, has ITC earned two outside sales?';
 c.answer='No. A transfer between ITC’s own reported businesses can appear in their segment activity, but it is not another sale to an outside customer. Internal revenue must be removed in the reconciliation. This is why adding every segment’s revenue can overstate the company’s outside sales.';
 const additions=[['Agricultural products and sourcing',urls.agri],['Paperboards and specialty papers',urls.paper],['Packaging and printing',urls.packaging],['ITC Infotech business',urls.technology],['Group companies and hotel relationship',urls.group],['FY 2025–26 results presentation',source]];
 c.sources.push(...additions.filter(([,url])=>!c.sources.some(([,old])=>old===url)));
 const basics=`<section class="content-section company-primer" id="itc-basics"><div class="number">START WITH WHAT IT SELLS</div><h2>ITC is several businesses under one roof.</h2><p>You might recognise an Aashirvaad flour pack, a Sunfeast biscuit or a Classmate notebook. Those products introduce ITC, but the business also serves customers you do not see at a supermarket: companies buying agricultural products, paper, packaging or technology services.</p><dl class="primer-definitions"><div><dt>Company → ITC</dt><dd>The organisation bringing together the businesses. Its overall performance depends on what those activities earn and the money they need.</dd></div><div><dt>Brand → Aashirvaad</dt><dd>A name used to sell products. One brand can contain different products, sizes and prices. Brand recognition is different from a profit disclosure.</dd></div><div><dt>Business segment → FMCG – Other products</dt><dd>A reporting group that combines activities such as packaged foods, personal care and stationery. FMCG means fast-moving consumer goods: everyday items bought and replaced regularly.</dd></div><div><dt>Business customer → a packaging buyer</dt><dd>A company buying material or a service for its own operations. This is called business-to-business (B2B), unlike selling a finished consumer product to a household.</dd></div></dl>${note(urls.profile,'ITC business profile')}
 <h3>The business map: what is supplied, and to whom?</h3><div class="primer-groups">${[
 ['Cigarettes','Gold Flake, Classic, India Kings and other cigarette brands.','Consumer purchases through the distribution and retail channel.','A separately reported consumer business whose prices, taxes, regulation and demand need their own explanation.',urls.cigarettes],
 ['Other consumer goods','Foods such as Aashirvaad, Sunfeast, Bingo! and YiPPee!; personal-care brands such as Fiama and Savlon; Classmate stationery, Mangaldeep incense and safety matches.','Households and other users buying through shops, retail chains and online channels.','Ingredients, pack sizes, brand spending and routes to market differ. Biscuits, soap and notebooks do not have identical buying patterns or costs.',urls.fmcg],
 ['Agricultural products','Crops and prepared produce such as grains, animal-feed ingredients and coffee, bought and supplied to business customers.','Business customers in India and overseas, as well as sourcing needs inside ITC.','ITC must buy suitable produce, prepare or move it as required and collect payment from buyers. Crop availability, purchase prices, selling prices and transport costs affect what remains.',urls.agri],
 ['Paperboards, paper and packaging','Paperboard and specialty paper; printed cartons, flexible packaging and other packaging solutions.','External business customers and ITC’s own consumer-goods businesses.','Paperboard is thick, stiff paper used to make packs. Packaging work turns materials into boxes, wrappers or other finished packs. The financial table groups these activities, so do not expect separate profit figures for every type of box.',urls.paper],
 ['Technology services through ITC Infotech','Helping other companies build, change or run computer programs and systems, through ITC Infotech.','Other companies buying technology services across industries.','Customers pay for agreed computer-system work and support. Engineers and other staff cost money. ITC Infotech has its own company accounts. The figures at the end cover ITC Limited itself, so they do not directly show this subsidiary’s sales.',urls.technology]
 ].map(([name,offering,buyer,meaning,url])=>`<div><h3>${name}</h3><p><strong>What it supplies:</strong> ${offering}</p><p><strong>Who buys:</strong> ${buyer}</p><p>${meaning}</p>${note(url,'Official business reference')}</div>`).join('')}</div>${note(urls.packaging,'Packaging: materials turned into finished packs')}<p class="source-note">The opening shelf combines selected product photos with clearly labelled explanatory illustrations. Brand names identify business exposure. Tobacco brands are listed for company research.</p>
 <h3>How does a sale become earnings?</h3><p>ITC receives revenue for products or services supplied. Buying raw materials, making goods, moving stock, advertising, running factories and delivering services all cost money. Taxes and the exact reporting definition also matter. The amount left under a stated profit measure can differ greatly between businesses with similar sales.</p><p>A pack’s shop price is not automatically the revenue ITC keeps, and revenue is not profit. The shopping channel and taxes affect the route from a consumer payment to the company’s accounts.</p></section>`;
 const specifics=`<section class="content-section company-primer" id="itc-specifics"><div class="number">WHAT IS DISTINCTIVE ABOUT ITC?</div><h2>Follow the connections between its businesses.</h2><h3>One group can be both a supplier and a brand owner</h3><ol class="primer-route"><li><strong>Buying crops and ingredients</strong><span>ITC buys agricultural produce for business customers and helps arrange ingredients for its own foods business.</span></li><li><strong>Consumer products</strong><span>Its foods business turns ingredients into branded products, arranging manufacturing, quality control, marketing and distribution.</span></li><li><strong>Packaging support</strong><span>ITC’s packaging business supplies packs to its consumer businesses and to outside companies.</span></li><li><strong>The outside customer</strong><span>A product eventually reaches a retailer, household or other external buyer. This is different from moving material between ITC’s businesses.</span></li></ol><p>These are connected activities, not a claim that every ITC product follows this exact route. The word <strong>synergy</strong> means businesses may benefit from shared capabilities. You still need evidence that the connection saves costs, improves quality or generates better returns.</p>${note(urls.agri,'ITC agri sourcing for its foods business')}${note(urls.packaging,'ITC packaging for internal and outside customers')}
 <details class="primer-detail"><summary>Why can adding segment sales count the same activity twice?</summary><p>Imagine produce is supplied internally to a foods business, which then sells a finished product outside ITC. Segment reporting can record the internal supply as part of one business’s activity. Adding that internal amount again to the outside sale would overstate the company’s external revenue. ITC publishes a deduction for inter-segment revenue; the actual reconciliation is at the end of this page.</p><p>This is an explanation of the reporting mechanism, not a claim about the supply route or profit of a particular brand.</p></details>
 <h3>Popularity, profit and cash answer different questions</h3><div class="primer-examples"><div><h4>Popularity: do customers choose it?</h4><p>A familiar brand may attract purchases. Look at demand, quantities and repeat use where disclosed.</p><span>Recognition alone does not tell you the costs of making and selling the product.</span></div><div><h4>Profit: what remains under the stated measure?</h4><p>Read each business’s segment result alongside sales. A growing consumer business can still contribute far less earnings than another activity.</p><span>A segment result groups businesses; it is not a profit number for each food, soap or notebook brand.</span></div><div><h4>Cash: what money is actually available?</h4><p>Stock, customer payments still due, new factories and acquisitions can require funding.</p><span>Accounting profit is different from cash collected, and investment spending has to be considered separately.</span></div></div>
 <h3>Hotels and subsidiaries: understand the boundary</h3><p>The hotel business was separated into ITC Hotels. ITC still identifies it as an associate, so separation does not mean every financial connection disappeared. Hotel operating sales should not be inserted into the parent-company segment table below.</p><p>A <strong>subsidiary</strong> is a company controlled by another company; ITC Infotech is an example. <strong>Standalone</strong> accounts cover ITC Limited itself. <strong>Consolidated</strong> accounts bring in controlled subsidiaries and account for other group investments under the applicable rules. Compare like with like before explaining growth.</p>${note(urls.group,'ITC group companies and relationships')}${note(source,'Results presentation: standalone and consolidated scopes','FY 2025–26')}
 <details class="primer-detail"><summary>Useful words for reading ITC’s business reviews</summary><dl class="primer-glossary">${[
 ['Volume, price and mix','Volume means quantities sold; price is what is charged on the stated basis; mix describes which products or formats make up sales. Each can change revenue differently.'],
 ['Margin','A specified profit measure divided by the corresponding revenue. Always check which costs are included in that profit measure and how taxes are treated in revenue.'],
 ['PBIT','Profit before interest and tax. The table uses reported segment PBIT, which must still be reconciled with company-level items; it is not profit after tax.'],
 ['Commodity','A traded agricultural product or raw material, such as wheat, coffee, wood or pulp. Its price can change with supply, demand, harvests and other market conditions.'],
 ['A business cycle','A period of changing demand, supply, selling prices and costs. Paper can face a different cycle from food or cigarettes.'],
 ['Working capital','Money tied to stock and customer amounts still due, alongside supplier payments. It helps explain why growth or profit need not immediately become cash.'],
 ['Capital allocation','Deciding where money is used: facilities, acquisitions, other investments or distributions. Ask what each use is expected to achieve and what evidence follows.']
 ].map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl></details><p class="source-note">Business explanations checked 29 October 2026 against the linked ITC business pages and FY 2025–26 results. The existing product catalogue groups variants and is not a separate earnings disclosure for each brand.</p></section>`;
 function numbers(){const f=window.COMPANY_FINANCIALS[id],cig=f.rows.find(r=>r.name==='FMCG – Cigarettes'),other=f.rows.find(r=>r.name==='FMCG – Other products');return `<div class="primer-number-guide"><h3>What these ITC figures mean in plain language</h3><p>Of every ₹100 of the <strong>combined reported segment result</strong>, approximately <strong>₹${(cig.profit/f.profitTotal*100).toFixed(2)}</strong> came from cigarettes and <strong>₹${(other.profit/f.profitTotal*100).toFixed(2)}</strong> from other FMCG products in this reporting year.</p><p>Calculated as the relevant segment result ÷ the reported segment-result total × 100. The total includes the loss in Other businesses. These are contributions to segment earnings, <strong>not product margins, profit after tax or a shareholder’s return</strong>. They explain why ITC cannot be understood from a food-brand shopping list alone.</p><p><strong>Read the two “other” labels separately:</strong> FMCG – Other products is the consumer-goods bundle that includes foods, personal care and stationery. Other businesses is a separate reported row.</p><details class="primer-detail"><summary>Why the sales rows do not add up to outside sales</summary><p>ITC reports ₹90,713 crore of total segment revenue, then deducts ₹9,846 crore of inter-segment revenue to reach ₹80,867 crore of gross revenue. Internal activity is removed to avoid counting it as another outside sale. Independently rounded segment rows differ from the reported total by ₹1 crore.</p></details><details class="primer-detail"><summary>Why cigarette revenue needs an extra check</summary><p>The presentation says cigarette taxation changed from 1 February 2026. Gross revenue and excise duties for the quarter and full year are therefore not strictly comparable with the previous year. Do not read the gross revenue growth rate as if it were the same as quantity growth or profit growth. This page does not estimate how much each tax change altered demand.</p></details><details class="primer-detail"><summary>What this standalone table leaves out</summary><p>This is the parent company’s segment statement. It does not show ITC Infotech’s sales as a separate technology business, and its Other businesses row is not a proxy for that subsidiary. Consult consolidated reporting and the relevant subsidiary accounts for the wider group. Company profit also includes reconciling items beyond the segment result.</p></details><p>For the next financial checks, read operating cash flow, stock and customer-payment balances, investment spending and acquisition notes. Those checks help connect the earnings story to the cash needed to run and expand the business.</p>${note(f.source,'Source for the figures and calculations',esc(f.location))}</div>`}
 if(window.PRODUCT_VISUALS){const existing=window.PRODUCT_VISUALS[id],byName=name=>existing.find(p=>p.name===name);const drawings=[
  ['Cigarettes business','Cigarette brands · separate reporting segment','cigarettes',urls.cigarettes],
  ['Agri business','Agricultural sourcing and business customers','agri',urls.agri],
  ['Paper & packaging','Materials and packs for business customers','paper-packaging',urls.packaging],
  ['ITC Infotech','Technology services · group subsidiary','technology',urls.technology]
 ].map(([name,category,slug,url])=>({name,category,url,image:`assets/products/itc-business-${slug}.svg`,kind:'illustration',alt:`${name} — conceptual illustration, not a product photograph`}));
 const first=[byName('Sunfeast Bounce'),byName('Savlon')].filter(Boolean);window.PRODUCT_VISUALS[id]=[...first,...drawings,...existing.filter(p=>!first.includes(p))];}
 window.companyPrimer={skipBusiness(company){return company.id===id||!!previous?.skipBusiness(company);},render(company,slot){if(company.id!==id)return previous?.render(company,slot)||'';return slot==='basics'?basics:slot==='specifics'?specifics:slot==='numbers'?numbers():'';},contents(company){return company.id===id?[['itc-basics','ITC from the basics'],['itc-specifics','How ITC’s businesses connect']]:previous?.contents(company)||[]}};
})();
